-- Automatic human-readable course code, generated by PostgreSQL to avoid duplicates.
create sequence if not exists public.cursos_codigo_seq start with 1;

alter table public.cursos
  add column if not exists codigo text;

create or replace function public.set_curso_codigo()
returns trigger
language plpgsql
set search_path = ''
as $function$
begin
  if new.codigo is null or btrim(new.codigo) = '' then
    new.codigo := 'CUR-' || lpad(nextval('public.cursos_codigo_seq'::regclass)::text, 4, '0');
  end if;
  return new;
end;
$function$;

revoke all on function public.set_curso_codigo() from public, anon, authenticated;

drop trigger if exists cursos_codigo_automatico on public.cursos;
create trigger cursos_codigo_automatico
before insert on public.cursos
for each row execute function public.set_curso_codigo();

do $migration$
declare
  v_row record;
begin
  for v_row in
    select id from public.cursos where codigo is null or btrim(codigo) = '' order by created_at, id
  loop
    update public.cursos
       set codigo = 'CUR-' || lpad(nextval('public.cursos_codigo_seq'::regclass)::text, 4, '0')
     where id = v_row.id;
  end loop;
end;
$migration$;

create unique index if not exists cursos_codigo_uidx on public.cursos (codigo);
alter table public.cursos alter column codigo set not null;
